// Crawled data integration

interface _CrawledRawItem {
  id: string;
  name: string;
  category: string;
  source_url: string;
  provider: string;
  deadline_hints: string[];
  value_status: string;
  value_basis_hint: string;
  review_priority: string;
  status: string;
  source: "crawled" | "crawled_enriched";
  // fields added by src/server/enrichment/enrich-crawled-data.py
  estimated_value?: number | null;
  value_basis?: string;
  subtitle?: string;
  unit?: string;
  eligibility?: string;
  how_to_apply?: string[];
  apply_url?: string | null;
  deadline_date?: string | null;
  tags?: string[];
  is_benefit?: boolean;
  first_seen?: string | null;
}

const _CRAWLED_CATEGORY_MAP: Record<string, Category> = {
  learning: "learning",
  scholarship: "scholarship",
  experience: "experience",
  culture: "culture",
  welfare: "welfare",
  career: "career",
  facility: "facility",
  sports: "sports",
  announcements: "culture",
  related: "learning",
  affiliated: "experience",
  other: "learning",
};

function _crawledToPongItem(raw: _CrawledRawItem): PongItem {
  const cat = (_CRAWLED_CATEGORY_MAP[raw.category] ?? "learning") as Category;
  const estimatedValue = raw.estimated_value ?? 0;
  return {
    id: raw.id,
    category: cat,
    category_label: CATEGORY_META[cat].label,
    name: raw.name,
    value: estimatedValue,
    value_basis: raw.value_basis ?? raw.value_basis_hint ?? "",
    unit: raw.unit ?? "1회",
    private_price: estimatedValue,
    school_price: 0,
    verified: false,
    source: raw.source_url,
    description: "",
    how_to_apply: raw.how_to_apply ?? [],
    eligibility: raw.eligibility ?? "서울대 학부생",
    duration_minutes: null,
    deadline_type: raw.deadline_hints.length > 0 ? "once" : "always",
    deadline_label:
      raw.deadline_hints.length > 0 ? raw.deadline_hints[0] : "상시",
    url: raw.apply_url ?? raw.source_url,
    provider: raw.provider,
    is_crawled: true,
    value_status: raw.value_status as "needs_estimation" | "verified" | "estimated",
    review_priority: raw.review_priority as "high" | "medium",
    estimated_value: raw.estimated_value,
    subtitle: raw.subtitle,
    apply_url: raw.apply_url,
    deadline_date: raw.deadline_date,
    tags: raw.tags ?? [],
    first_seen: raw.first_seen ?? null,
  };
}

const _verifiedUrls = new Set(
  _verifiedItems.map((i) => i.url).filter(Boolean)
);
function _todayISO(): string {
  const now = new Date();
  const kst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
  return kst.toISOString().slice(0, 10);
}

function _isExpired(deadlineDate?: string | null): boolean {
  if (!deadlineDate) return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(deadlineDate)) return false;
  return deadlineDate < _todayISO();
}

const _crawledConverted = (_sourceData as _CrawledRawItem[])
  .filter((raw) => raw.is_benefit !== false)
  .filter((raw) => !_isExpired(raw.deadline_date))
  .map(_crawledToPongItem)
  .filter((c) => !_verifiedUrls.has(c.url));

export const items: PongItem[] = [
  ..._verifiedItems,
  ..._crawledConverted.filter((c) => c.review_priority === "high"),
  ..._crawledConverted.filter((c) => c.review_priority !== "high"),
];

export const totalClaimableValue = items.reduce(
  (sum, item) => sum + item.value,
  0
);

export function getItemsByCategory(category: Category): PongItem[] {
  return items.filter((i) => i.category === category);
}

export function getItem(id: string): PongItem | undefined {
  return items.find((i) => i.id === id);
}

export function getTodayNewCount(): number {
  const kstToday = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().slice(0, 10);
  return items.filter((i) => i.first_seen && i.first_seen.slice(0, 10) === kstToday).length;
}

export function getTagsForCategory(category: Category): { tag: string; count: number }[] {
  const counter = new Map<string, number>();
  for (const item of items) {
    if (item.category !== category) continue;
    for (const t of item.tags ?? []) {
      counter.set(t, (counter.get(t) ?? 0) + 1);
    }
  }
  return Array.from(counter.entries())
    .map(([tag, count]) => ({ tag, count }))
    .sort((a, b) => b.count - a.count);
}

export function filterByTags(list: PongItem[], selectedTags: string[]): PongItem[] {
  if (selectedTags.length === 0) return list;
  return list.filter((item) => {
    const itemTags = item.tags ?? [];
    return selectedTags.every((t) => itemTags.includes(t));
  });
}
